import csv
import io

PARTICIPANT_FIELDS = ('id', 'name', 'email', 'first_choice', 'second_choice', 'group_id')


def allocate(participants, rooms, workshops):
    """Allocate a parsed roster without normalizing any source values."""
    errors = []
    collections = [('participants', participants), ('rooms', rooms), ('workshops', workshops)]
    for label, value in collections:
        if not isinstance(value, list):
            errors.append(label + ' must be an array.')
    if errors:
        return {'assignments': [], 'waitlist': [], 'errors': errors}

    def check_strings(record, fields, required_nonempty, label):
        valid = True
        for field in fields:
            value = record.get(field)
            if not isinstance(value, str):
                errors.append(label + ': ' + field + ' must be a string.')
                valid = False
            elif field in required_nonempty and not value.strip():
                errors.append(label + ': ' + field + ' must be nonempty.')
                valid = False
        return valid

    room_map = {}
    workshop_map = {}
    seen_rooms = set()
    for index, room in enumerate(rooms):
        label = 'Room ' + str(index + 1)
        if not isinstance(room, dict):
            errors.append(label + ' must be an object.')
            continue
        valid = check_strings(room, ('id', 'name'), ('id',), label)
        capacity = room.get('capacity')
        if type(capacity) is not int or capacity < 0:
            errors.append(label + ': capacity must be a nonnegative integer.')
            valid = False
        if type(room.get('open')) is not bool:
            errors.append(label + ': open must be a boolean.')
            valid = False
        rid = room.get('id')
        if isinstance(rid, str) and rid.strip():
            if rid in seen_rooms:
                errors.append(label + ': duplicate room ID ' + repr(rid) + '.')
                valid = False
            seen_rooms.add(rid)
        if valid:
            room_map[rid] = room

    seen_workshops = set()
    referenced_rooms = set()
    for index, workshop in enumerate(workshops):
        label = 'Workshop ' + str(index + 1)
        if not isinstance(workshop, dict):
            errors.append(label + ' must be an object.')
            continue
        valid = check_strings(workshop, ('id', 'name', 'room', 'time'), ('id', 'room'), label)
        wid = workshop.get('id')
        rid = workshop.get('room')
        if isinstance(wid, str) and wid.strip():
            if wid in seen_workshops:
                errors.append(label + ': duplicate workshop ID ' + repr(wid) + '.')
                valid = False
            seen_workshops.add(wid)
        if isinstance(rid, str):
            if rid not in seen_rooms:
                errors.append(label + ': room does not reference an existing room.')
                valid = False
            if rid in referenced_rooms:
                errors.append(label + ': multiple workshops referencing the same room are unsupported.')
                valid = False
            referenced_rooms.add(rid)
        if valid:
            workshop_map[wid] = workshop

    seen_ids = set()
    seen_emails = set()
    for index, participant in enumerate(participants):
        label = 'Participant ' + str(index + 1)
        if not isinstance(participant, dict):
            errors.append(label + ' must be an object.')
            continue
        check_strings(participant, PARTICIPANT_FIELDS, ('id', 'name', 'email', 'first_choice'), label)
        for field, seen in (('id', seen_ids), ('email', seen_emails)):
            value = participant.get(field)
            if isinstance(value, str) and value.strip():
                if value in seen:
                    errors.append(label + ': duplicate participant ' + field + ' ' + repr(value) + '.')
                seen.add(value)
        first = participant.get('first_choice')
        second = participant.get('second_choice')
        if isinstance(first, str) and first not in seen_workshops:
            errors.append(label + ': first_choice must reference an existing workshop.')
        if isinstance(second, str) and second != '' and second not in seen_workshops:
            errors.append(label + ': second_choice must be empty or reference an existing workshop.')

    if errors:
        return {'assignments': [], 'waitlist': [], 'errors': errors}

    units = []
    groups = {}
    for index, participant in enumerate(participants):
        group = participant['group_id']
        if group != '':
            if group not in groups:
                groups[group] = []
                units.append(groups[group])
            groups[group].append(index)
        else:
            units.append([index])

    remaining = {rid: room['capacity'] for rid, room in room_map.items()}
    assigned = {}
    waiting = {}
    for unit in units:
        leader = participants[unit[0]]
        candidates = list(dict.fromkeys(choice for choice in (leader['first_choice'], leader['second_choice']) if choice != ''))
        selected = None
        failures = []
        for wid in candidates:
            workshop = workshop_map[wid]
            rid = workshop['room']
            if not all(wid in (participants[index]['first_choice'], participants[index]['second_choice']) for index in unit):
                failures.append('Workshop ' + repr(wid) + ' is not accepted by every booking member.')
            elif not room_map[rid]['open']:
                failures.append('The room for workshop ' + repr(wid) + ' is closed.')
            elif remaining[rid] < len(unit):
                failures.append('Workshop ' + repr(wid) + ' has insufficient remaining seats for the entire booking.')
            else:
                selected = wid
                remaining[rid] -= len(unit)
                break
        for index in unit:
            participant = participants[index]
            base = {'participant_id': participant['id'], 'group_id': participant['group_id']}
            if selected is None:
                waiting[index] = dict(base, reason=' '.join(failures) or 'No acceptable workshop is available for the entire booking.')
            else:
                assigned[index] = dict(base, workshop_id=selected, room_id=workshop_map[selected]['room'], choice_rank=1 if participant['first_choice'] == selected else 2)

    return {'assignments': [assigned[i] for i in range(len(participants)) if i in assigned], 'waitlist': [waiting[i] for i in range(len(participants)) if i in waiting], 'errors': []}


def clean_csv(contents, workshops):
    """Clean CSV registrations, keeping only the first valid row per email."""
    participants = []
    rejected = []
    errors = []
    known = {w['id'] for w in workshops if isinstance(w, dict) and isinstance(w.get('id'), str)} if isinstance(workshops, list) else set()
    ids = set()
    emails = set()
    for filename, content in contents:
        if not isinstance(content, str):
            errors.append('CSV content must be a string.')
            continue
        try:
            reader = csv.reader(io.StringIO(content), strict=True)
            header = next(reader, None)
            if header is None:
                errors.append('CSV has no header.')
                continue
            header = [v.strip().lstrip('\ufeff') for v in header]
            if len(header) != len(set(header)) or not all(field in header for field in PARTICIPANT_FIELDS):
                errors.append('CSV header must contain each required participant field exactly once.')
                continue
            for row in reader:
                if not row or all(not value.strip() for value in row):
                    continue
                reasons = []
                if len(row) != len(header):
                    reasons.append('Row has a different number of columns than the header.')
                    participant = None
                else:
                    raw = dict(zip(header, row))
                    participant = {field: ' '.join(raw[field].split()) for field in PARTICIPANT_FIELDS}
                    participant['email'] = participant['email'].lower()
                    for field in ('id', 'name', 'email', 'first_choice'):
                        if not participant[field]:
                            reasons.append(field + ' must be nonempty.')
                    if participant['id'] in ids:
                        reasons.append('Duplicate participant ID.')
                    if participant['email'] in emails:
                        reasons.append('Duplicate email; the first valid registration is retained.')
                    if participant['first_choice'] not in known:
                        reasons.append('Invalid first_choice workshop ID.')
                    if participant['second_choice'] and participant['second_choice'] not in known:
                        reasons.append('Invalid second_choice workshop ID.')
                if reasons:
                    rejected.append({'file': filename, 'row': reader.line_num, 'values': row, 'reasons': reasons})
                else:
                    participants.append(participant)
                    ids.add(participant['id'])
                    emails.add(participant['email'])
        except csv.Error as exc:
            errors.append('Invalid CSV: ' + str(exc))
    output = io.StringIO(newline='')
    writer = csv.DictWriter(output, fieldnames=PARTICIPANT_FIELDS, lineterminator='\n')
    writer.writeheader()
    writer.writerows(participants)
    return participants, output.getvalue(), rejected, errors


def run(data):
    if not isinstance(data, dict):
        return {'assignments': [], 'waitlist': [], 'errors': ['Input must be an object.']}
    rooms = data.get('rooms')
    workshops = data.get('workshops')
    if 'participants' in data:
        return allocate(data['participants'], rooms, workshops)
    contents = []
    if 'csv' in data:
        contents.append(('', data['csv']))
    elif 'registration_csv' in data:
        contents.append(('', data['registration_csv']))
    elif isinstance(data.get('files'), list):
        for file in data['files']:
            if not isinstance(file, dict):
                return {'assignments': [], 'waitlist': [], 'errors': ['Each CSV file must be an object with content.']}
            contents.append((file.get('name', ''), file.get('content')))
    else:
        return {'assignments': [], 'waitlist': [], 'errors': ['participants or registration CSV content is required.']}
    participants, cleaned_csv, rejected, cleaning_errors = clean_csv(contents, workshops)
    result = allocate(participants, rooms, workshops)
    if cleaning_errors:
        result = {'assignments': [], 'waitlist': [], 'errors': cleaning_errors + result['errors']}
    result.update({'participants': participants, 'cleaned_csv': cleaned_csv, 'rejected_rows': rejected})
    return result

import csv
import io
from collections import Counter

FIELDS = ('id', 'name', 'email', 'first_choice', 'second_choice', 'group_id')


def _empty_clean(errors):
    return {'participants': [], 'cleaned_csv': '', 'rejected_rows': [], 'errors': errors}


def _valid_email(email):
    if email.count('@') != 1 or any(c.isspace() for c in email):
        return False
    local, domain = email.split('@')
    return bool(local and domain)


def clean_registration_csv(csv_text, workshop_ids):
    """Clean workshop registration CSV independently of allocation."""
    if not isinstance(csv_text, str):
        return _empty_clean(['csv_text must be a string.'])
    if not isinstance(workshop_ids, list) or any(not isinstance(x, str) for x in workshop_ids):
        return _empty_clean(['workshop_ids must be an array of strings.'])
    known = set(workshop_ids)
    reader = csv.reader(io.StringIO(csv_text, newline=''), strict=True)
    try:
        headers = next(reader)
    except StopIteration:
        return _empty_clean(['The CSV is missing its required header row.'])
    except csv.Error as exc:
        return _empty_clean(['Malformed CSV header: ' + str(exc)])
    headers = [h.strip() for h in headers]
    errors = []
    duplicates = [h for h, count in Counter(headers).items() if count > 1]
    missing = [h for h in FIELDS if h not in headers]
    extra = list(dict.fromkeys(h for h in headers if h not in FIELDS))
    if duplicates:
        errors.append('Duplicate CSV headers: ' + ', '.join(repr(h) for h in duplicates) + '.')
    if missing:
        errors.append('Missing required CSV headers: ' + ', '.join(missing) + '.')
    if extra:
        errors.append('Unsupported CSV headers: ' + ', '.join(repr(h) for h in extra) + '.')
    if errors:
        return _empty_clean(errors)
    participants, rejected = [], []
    seen_ids, seen_emails = set(), set()
    while True:
        row_number = reader.line_num + 1
        try:
            row = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            rejected.append({'row_number': row_number, 'id': '', 'email': '', 'reason': 'Malformed CSV row: ' + str(exc)})
            continue
        values = [v.strip() for v in row]
        partial = dict(zip(headers, values))
        identifier = partial.get('id', '')
        email = partial.get('email', '').lower()
        if len(row) != len(FIELDS):
            rejected.append({'row_number': row_number, 'id': identifier, 'email': email, 'reason': 'Malformed row: expected six fields.'})
            continue
        p = {field: partial[field] for field in FIELDS}
        p['name'] = ' '.join(p['name'].split())
        p['email'] = email
        reasons = []
        if not identifier:
            reasons.append('Missing ID.')
        elif identifier in seen_ids:
            reasons.append('Duplicate ID among previously accepted registrations.')
        if not p['name']:
            reasons.append('Empty name.')
        if not _valid_email(email):
            reasons.append('Invalid email: require one @, nonempty local and domain portions, and no whitespace.')
        if not p['first_choice'] or p['first_choice'] not in known:
            reasons.append('Unknown or empty first_choice.')
        if p['second_choice'] and p['second_choice'] not in known:
            reasons.append('Unknown second_choice.')
        if not reasons and email in seen_emails:
            reasons.append('Duplicate email: the first valid registration is retained.')
        if reasons:
            rejected.append({'row_number': row_number, 'id': identifier, 'email': email, 'reason': ' '.join(reasons)})
        else:
            participants.append(p)
            seen_ids.add(identifier)
            seen_emails.add(email)
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(FIELDS)
    writer.writerows([p[f] for f in FIELDS] for p in participants)
    return {'participants': participants, 'cleaned_csv': output.getvalue(), 'rejected_rows': rejected, 'errors': []}


def _configuration(rooms, workshops):
    errors, room_map, workshop_map = [], {}, {}
    if not isinstance(rooms, list) or not isinstance(workshops, list):
        return {}, {}, ['rooms and workshops must be arrays.']
    for index, room in enumerate(rooms):
        label = 'Room at index ' + str(index)
        if not isinstance(room, dict):
            errors.append(label + ' must be an object.')
            continue
        identifier = room.get('id')
        if not isinstance(identifier, str) or not identifier:
            errors.append(label + ' must have a nonempty string ID.')
            continue
        if identifier in room_map:
            errors.append('Duplicate room ID: ' + identifier + '.')
        capacity = room.get('capacity')
        if type(capacity) is not int or capacity < 0:
            errors.append(label + ' capacity must be a nonnegative integer.')
        if type(room.get('open')) is not bool:
            errors.append(label + ' open must be a boolean.')
        room_map[identifier] = room
    for index, workshop in enumerate(workshops):
        label = 'Workshop at index ' + str(index)
        if not isinstance(workshop, dict):
            errors.append(label + ' must be an object.')
            continue
        identifier = workshop.get('id')
        if not isinstance(identifier, str) or not identifier:
            errors.append(label + ' must have a nonempty string ID.')
            continue
        if identifier in workshop_map:
            errors.append('Duplicate workshop ID: ' + identifier + '.')
        room_id = workshop.get('room')
        if not isinstance(room_id, str) or room_id not in room_map:
            errors.append(label + ' references an unknown room.')
        workshop_map[identifier] = workshop
    return room_map, workshop_map, errors


def allocate_workshops(participants, rooms, workshops):
    """Allocate a parsed, cleaned roster without parsing or cleaning CSV.

    Seats are shared by room. Booking units are considered in first-member
    order; output entries are emitted in participant roster order.
    """
    room_map, workshop_map, errors = _configuration(rooms, workshops)
    if not isinstance(participants, list):
        errors.append('participants must be an array.')
    else:
        ids, emails = set(), set()
        for index, p in enumerate(participants):
            label = 'Participant at index ' + str(index)
            if not isinstance(p, dict) or any(not isinstance(p.get(f), str) for f in FIELDS):
                errors.append(label + ' must contain the six registration fields as strings.')
                continue
            if not p['id'] or p['id'] in ids:
                errors.append(label + ' has a missing or duplicate ID.')
            if not p['name'].strip():
                errors.append(label + ' has an empty name.')
            if not _valid_email(p['email']) or p['email'].lower() in emails:
                errors.append(label + ' has an invalid or duplicate email.')
            if p['first_choice'] not in workshop_map:
                errors.append(label + ' has an unknown or empty first_choice.')
            if p['second_choice'] and p['second_choice'] not in workshop_map:
                errors.append(label + ' has an unknown second_choice.')
            ids.add(p['id'])
            emails.add(p['email'].lower())
    if errors:
        return {'assignments': [], 'waitlist': [], 'errors': errors}
    units, groups = [], {}
    for index, p in enumerate(participants):
        group = p['group_id']
        if group:
            if group not in groups:
                groups[group] = []
                units.append(groups[group])
            groups[group].append(index)
        else:
            units.append([index])
    remaining = {key: room['capacity'] for key, room in room_map.items()}
    selected = {}
    for unit in units:
        leader = participants[unit[0]]
        for choice in dict.fromkeys((leader['first_choice'], leader['second_choice'])):
            if not choice:
                continue
            if not all(choice in (participants[i]['first_choice'], participants[i]['second_choice']) for i in unit):
                continue
            room_id = workshop_map[choice]['room']
            if not room_map[room_id]['open'] or remaining[room_id] < len(unit):
                continue
            remaining[room_id] -= len(unit)
            for i in unit:
                selected[i] = (choice, room_id)
            break
    assignments, waitlist = [], []
    for index, p in enumerate(participants):
        if index in selected:
            workshop_id, room_id = selected[index]
            assignments.append({'participant_id': p['id'], 'workshop_id': workshop_id, 'room_id': room_id})
        else:
            waitlist.append({'participant_id': p['id'], 'reason': 'No mutually accepted choice has an open room with enough seats for the entire booking unit.'})
    return {'assignments': assignments, 'waitlist': waitlist, 'errors': []}


def run(data):
    if not isinstance(data, dict):
        return _empty_clean(['Input must be an object.'])
    allocating = 'rooms' in data or 'workshops' in data
    if 'participants' in data and 'csv_text' not in data and 'files' not in data:
        result = allocate_workshops(data['participants'], data.get('rooms'), data.get('workshops'))
        return {'participants': data['participants'], **result}
    text = data.get('csv_text')
    if text is None and 'files' in data:
        files = data['files']
        if not isinstance(files, list) or len(files) != 1 or not isinstance(files[0], dict):
            result = _empty_clean(['Supply exactly one CSV file or csv_text; multiple files are unsupported.'])
            if allocating:
                result.update(assignments=[], waitlist=[])
            return result
        text = files[0].get('content')
    config_errors = []
    if allocating:
        _, workshop_map, config_errors = _configuration(data.get('rooms'), data.get('workshops'))
        workshop_ids = list(workshop_map)
    else:
        workshop_ids = data.get('workshop_ids')
    if config_errors:
        return {**_empty_clean(config_errors), 'assignments': [], 'waitlist': []}
    result = clean_registration_csv(text, workshop_ids)
    if allocating:
        if result['errors']:
            result.update(assignments=[], waitlist=[])
        else:
            allocation = allocate_workshops(result['participants'], data['rooms'], data['workshops'])
            result.update(allocation)
    return result
